18	)
19	
20	//go:embed dist/*
21	var embeddedFiles embed.FS
22	
23	const (
24		frontendHTMLCacheControl        = "no-cache, no-store, must-revalidate"
25		frontendStaticAssetCacheControl = "public, max-age=3600"
26		frontendHashedAssetCacheControl = "public, max-age=3600, immutable"
27	)
28	
29	type FrontendService struct {
30		Profile *profile.Profile
31		Store   *store.Store
32	}
33	
34	func NewFrontendService(profile *profile.Profile, store *store.Store) *FrontendService {
35		return &FrontendService{
36			Profile: profile,
37			Store:   store,
38		}
39	}
40	
41	func (s *FrontendService) Serve(_ context.Context, e *echo.Echo) {
42		frontendFS := getFileSystem("dist")
43		skipper := func(c *echo.Context) bool {
44			requestPath := c.Request().URL.Path
45			if shouldSkipFrontendStatic(requestPath) {
46				return true
47			}
48	
49			setFrontendCacheHeaders(c, requestPath)
50			return false
51		}
52	
53		// Route to serve the frontend static assets.
54		e.Use(middleware.StaticWithConfig(middleware.StaticConfig{
55			Filesystem: frontendFS,
56			Skipper:    skipper,
57		}))
58	
59		e.Use(spaFallbackMiddleware(frontendFS))
60		s.registerRoutes(e)
61	}
62	
63	func spaFallbackMiddleware(frontendFS fs.FS) echo.MiddlewareFunc {
64		return func(next echo.HandlerFunc) echo.HandlerFunc {
65			return func(c *echo.Context) error {
66				err := next(c)
67				if err == nil {
68					return nil
69				}
70	
71				requestPath := c.Request().URL.Path
72				if shouldSkipFrontendStatic(requestPath) || !shouldServeFrontendHTML(requestPath) || echo.StatusCode(err) != http.StatusNotFound {
73					return err
74				}
75	
76				setFrontendCacheHeaders(c, requestPath)
77				return c.FileFS("index.html", frontendFS)
78			}
79		}
80	}
81	
82	func shouldSkipFrontendStatic(requestPath string) bool {
83		if requestPath == "/robots.txt" || requestPath == "/sitemap.xml" || strings.HasSuffix(requestPath, "/rss.xml") {
84			return true
85		}
86		return hasPathPrefix(requestPath, "/api") ||
87			hasPathPrefix(requestPath, "/file") ||
88			requestPath == "/memos.api.v1" ||
89			strings.HasPrefix(requestPath, "/memos.api.v1.")
90	}
91	
92	func setFrontendCacheHeaders(c *echo.Context, requestPath string) {
93		if shouldServeFrontendHTML(requestPath) {
94			c.Response().Header().Set(echo.HeaderCacheControl, frontendHTMLCacheControl)
95			c.Response().Header().Set("Pragma", "no-cache")
96			c.Response().Header().Set("Expires", "0")
97			return
98		}
99	
100		cacheControl := frontendStaticAssetCacheControl
101		if strings.HasPrefix(requestPath, "/assets/") {
102			cacheControl = frontendHashedAssetCacheControl
103		}
104		c.Response().Header().Set(echo.HeaderCacheControl, cacheControl)
105	}
106	
107	func shouldServeFrontendHTML(requestPath string) bool {
108		return requestPath == "/" || requestPath == "/index.html" || path.Ext(requestPath) == ""
109	}
110	
111	func hasPathPrefix(requestPath, prefix string) bool {
112		return requestPath == prefix || strings.HasPrefix(requestPath, prefix+"/")
113	}
114	
115	func getFileSystem(path string) fs.FS {
116		sub, err := fs.Sub(embeddedFiles, path)
117		if err != nil {
118			panic(err)
119		}
120		return sub
121	}
122	
123	func (s *FrontendService) registerRoutes(e *echo.Echo) {
124		e.GET("/robots.txt", s.getRobotsTXT)
125		e.GET("/sitemap.xml", s.getSitemapXML)
126	}
127	
128	func (s *FrontendService) getRobotsTXT(c *echo.Context) error {
129		instanceURL, err := normalizeInstanceURL(s.Profile.InstanceURL)
130		if err != nil {
131			return err
132		}
133	
134		robotsTXT := strings.Join([]string{
135			"User-agent: *",
136			"Allow: /",
137			"Host: " + instanceURL,
138			"Sitemap: " + instanceURL + "/sitemap.xml",
139		}, "\n")
140		return c.String(http.StatusOK, robotsTXT)
141	}
142	
143	func (s *FrontendService) getSitemapXML(c *echo.Context) error {
144		instanceURL, err := normalizeInstanceURL(s.Profile.InstanceURL)
145		if err != nil {
146			return err
147		}
148	
149		memos, err := s.Store.ListMemos(c.Request().Context(), &store.FindMemo{
150			VisibilityList: []store.Visibility{store.Public},
151		})
152		if err != nil {
153			return errors.Wrap(err, "failed to list public memos for sitemap")
154		}
155	
156		urls := make([]sitemapURL, 0, len(memos))
157		for _, memo := range memos {
158			urls = append(urls, sitemapURL{
159				Loc: instanceURL + "/memos/" + memo.UID,
160			})
161		}
162	
163		return c.XML(http.StatusOK, sitemapURLSet{
164			XMLNS: sitemapXMLNamespace,
165			URLs:  urls,
166		})
167	}
168	
169	func normalizeInstanceURL(instanceURL string) (string, error) {
170		instanceURL = strings.TrimRight(instanceURL, "/")
171		if instanceURL == "" {
172			return "", echo.NewHTTPError(http.StatusNotFound, "instance URL is not configured")
173		}
174		return instanceURL, nil
175	}
176	
177	type sitemapURLSet struct {
178		XMLName xml.Name     `xml:"urlset"`
179		XMLNS   string       `xml:"xmlns,attr"`
180		URLs    []sitemapURL `xml:"url"`
181	}
182	
183	type sitemapURL struct {
184		Loc string `xml:"loc"`
185	}
186	
187	//nolint:revive
188	const sitemapXMLNamespace = "http://www.sitemaps.org/schemas/sitemap/0.9"
